#!/usr/bin/env node
/**
 * 只读抽检：import-*.json 批结果 + done 与 distill 标题缺口
 * 用法: node scripts/audit-import-snapshot.mjs [--out=path]
 */
import fs from "fs";
import path from "path";
import os from "os";

const BASE = path.join(os.homedir(), "Documents/deepseek-harness/default-workspace/memory-migration");
const TMP = os.tmpdir();
const DISTILL = path.join(BASE, "out/distilled-local/cursor");
const outArg = process.argv.find((a) => a.startsWith("--out="));
const OUT = outArg ? outArg.slice(6) : path.join(TMP, "import-audit-snapshot.json");

function walkMemTitles(dir) {
  const titles = new Set();
  if (!fs.existsSync(dir)) return titles;
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walkMemTitles(p).forEach((t) => titles.add(t));
    else if (e.name.endsWith(".json")) {
      try {
        const j = JSON.parse(fs.readFileSync(p, "utf8"));
        for (const m of j.memories || []) if (m.title) titles.add(m.title);
      } catch {}
    }
  }
  return titles;
}

const batchAudit = [];
for (const f of fs.readdirSync(TMP).filter((x) => x.startsWith("import-") && x.endsWith(".json") && !x.includes("local-sources"))) {
  let j;
  try {
    j = JSON.parse(fs.readFileSync(path.join(TMP, f), "utf8"));
  } catch {
    continue;
  }
  const proj = j.project || f;
  const batches = j.batches || [];
  if (!batches.length) continue;
  let ok = 0,
    failedZero = 0,
    timeout = 0,
    otherErr = 0;
  const riskyTitles = [];
  for (const b of batches) {
    if (b.error === "commit timeout") {
      timeout++;
      riskyTitles.push(...(b.titles || []));
      continue;
    }
    const st = b.result?.status;
    const ex = b.result?.extracted || {};
    if (st === "completed" && ((ex.memory_write || 0) > 0 || (ex.memory_edit || 0) > 0)) ok++;
    else if (st === "failed" || (st === "completed" && !ex.memory_write && !ex.memory_edit)) {
      failedZero++;
      riskyTitles.push(...(b.titles || []));
    } else if (b.error) otherErr++;
  }
  if (failedZero || timeout || otherErr)
    batchAudit.push({ project: proj, batches: batches.length, ok, failedZero, timeout, otherErr, riskyTitleCount: riskyTitles.length });
}

const gapAudit = [];
for (const f of fs.readdirSync(TMP).filter((x) => x.startsWith("done-ov-cursor-") && x.endsWith(".json"))) {
  const proj = f.slice("done-ov-cursor-".length, -5);
  let done = new Set();
  try {
    done = new Set(JSON.parse(fs.readFileSync(path.join(TMP, f), "utf8")));
  } catch {
    continue;
  }
  const all = walkMemTitles(path.join(DISTILL, proj));
  if (!all.size) continue;
  const missing = [...all].filter((t) => !done.has(t));
  if (missing.length)
    gapAudit.push({ project: proj, distill: all.size, done: done.size, missing: missing.length, sampleMissing: missing.slice(0, 3) });
}
gapAudit.sort((a, b) => b.missing - a.missing);
batchAudit.sort((a, b) => b.failedZero + b.timeout - (a.failedZero + a.timeout));

const report = {
  at: new Date().toISOString(),
  note: "只读抽检；与 OV 并行安全。勿同时跑第二个 import-to-ov 到同一 session。",
  batchIssues: batchAudit,
  distillDoneGaps: gapAudit,
  totals: {
    doneFiles: fs.readdirSync(TMP).filter((x) => x.startsWith("done-ov-cursor-")).length,
    importLogs: fs.readdirSync(TMP).filter((x) => x.startsWith("import-") && x.endsWith(".json")).length,
  },
};
fs.writeFileSync(OUT, JSON.stringify(report, null, 2), "utf8");
console.log("written", OUT);
console.log("batchIssues", batchAudit.length, "distillDoneGaps", gapAudit.length);
for (const r of gapAudit.slice(0, 8)) console.log(" gap", r.project, r.missing, "/", r.distill);
for (const r of batchAudit.slice(0, 8)) console.log(" batch", r.project, "fail0", r.failedZero, "timeout", r.timeout);
